16	// 失败必须以普通错误返回（不能伪装成摘要冲突、参数非法或无权操作），且交换
17	// 状态、回执与审计不能只有一部分成功：内部使用者看到的仍是待回执且无正式
18	// 回执的交换，失败尝试的原因与登记时间不留痕迹，既有审计事件完整保留、不
19	// 新增回执事件；交换标识、原包内容与摘要保持原样。保存条件恢复后，接收方
20	// 可用不同的非空原因成功登记（失败尝试不建立回执，不得报已有回执冲突），
21	// 正式原因与登记时间以成功这次为准，只新增一条回执审计。此后改变原因重交
22	// 仍返回 ErrConflict，相同回执重交返回原确认——既有公开行为不变。
23	func TestReceiptSaveFailureKeepsExchangeAndAudit(t *testing.T) {
24		dir := t.TempDir()
25		clk := &fakeClock{t: time.Date(2026, 6, 1, 9, 0, 0, 0, time.UTC)}
26		open := func() *Store {
27			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
28			if err != nil {
29				t.Fatalf("open: %v", err)
30			}
31			return s
32		}
33	
34		s := open()
35		p, err := s.RegisterPatient(doc, "回执保存失败患者")
36		if err != nil {
37			t.Fatal(err)
38		}
39		e, err := s.AddEncounter(doc, p.ID, time.Time{})
40		if err != nil {
41			t.Fatal(err)
42		}
43		rd, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "诊断v1内容")
44		if err != nil {
45			t.Fatal(err)
46		}
47		if _, err := s.ActivateRecord(doc, rd.ID); err != nil {
48			t.Fatal(err)
49		}
50		ro, err := s.CreateDraft(doc, p.ID, e.ID, Order, "医嘱v1内容")
51		if err != nil {
52			t.Fatal(err)
53		}
54		if _, err := s.ActivateRecord(doc, ro.ID); err != nil {
55			t.Fatal(err)
56		}
57		a, err := s.Grant(doc, p.ID, rcv.ID,
58			[]Scope{
59				{EncounterID: e.ID, Category: Diagnosis},
60				{EncounterID: e.ID, Category: Order},
61			},
62			clk.t.Add(-time.Minute), clk.t.Add(48*time.Hour))
63		if err != nil {
64			t.Fatal(err)
65		}
66	
67		// 已经成功创建、仍在等待回执的交换：登记回执的起点。
68		clk.t = clk.t.Add(time.Hour)
69		x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rd.ID, ro.ID}, "req-receipt-save")
70		if err != nil {
71			t.Fatal(err)
72		}
73		if x.Status != ExchangePending || x.Receipt != nil {
74			t.Fatalf("baseline exchange must be pending without receipt: %+v", x)
75		}
76	
77		// 提交前的正式基线：内部视图中的交换、交换列表、审计与接收方取包结果。
78		xBefore := snapshotExchange(x)
79		gotBefore, err := s.GetExchange(doc, p.ID, x.ID)
80		if err != nil {
81			t.Fatal(err)
82		}
83		assertExchangeMatches(t, gotBefore, xBefore, "baseline exchange")
84		listBefore, err := s.ListExchanges(doc, p.ID)
85		if err != nil {
86			t.Fatal(err)
87		}
88		auditBefore, err := s.AuditEvents(doc, p.ID)
89		if err != nil {
90			t.Fatal(err)
91		}
92		if got := auditActions(auditBefore)[ActionReceipted]; got != 0 {
93			t.Fatalf("baseline receipt events = %d, want 0", got)
94		}
95		deliveryBefore, err := s.FetchPackage(rcv, x.ID)
96		if err != nil {
97			t.Fatal(err)
98		}
99		if deliveryBefore.Digest != x.Digest || deliveryBefore.Status != ExchangePending {
100			t.Fatalf("unexpected baseline delivery: %+v", deliveryBefore)
101		}
102	
103		// checkIntact 断言：失败尝试之后（以及重开之后），交换仍是待回执且无
104		// 正式回执——失败尝试的原因与登记时间没有留下半条回执；审计、交换列表
105		// 与包内容/摘要全部维持提交前状态。
106		checkIntact := func(label string, st *Store) {
107			t.Helper()
108	
109			got, err := st.GetExchange(doc, p.ID, x.ID)
110			if err != nil {
111				t.Fatalf("%s: get exchange: %v", label, err)
112			}
113			assertExchangeMatches(t, got, xBefore, label+": exchange")
114			if got.Status != ExchangePending || got.Receipt != nil {
115				t.Fatalf("%s: failed attempt left a partial receipt: status=%q receipt=%+v",
116					label, got.Status, got.Receipt)
117			}
118	
119			xs, err := st.ListExchanges(doc, p.ID)
120			if err != nil {
121				t.Fatalf("%s: list exchanges: %v", label, err)
122			}
123			if !reflect.DeepEqual(xs, listBefore) {
124				t.Fatalf("%s: exchange list changed:\nbefore: %+v\nafter:  %+v", label, listBefore, xs)
125			}
126	
127			audit, err := st.AuditEvents(doc, p.ID)
128			if err != nil {
129				t.Fatalf("%s: audit: %v", label, err)
130			}
131			if !reflect.DeepEqual(audit, auditBefore) {
132				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
133			}
134			if got := auditActions(audit)[ActionReceipted]; got != 0 {
135				t.Fatalf("%s: failed attempt added %d receipt events", label, got)
136			}
137	
138			// 接收方取包仍得到原摘要与原包内容：登记失败没有重新生成包。
139			d, err := st.FetchPackage(rcv, x.ID)
140			if err != nil {
141				t.Fatalf("%s: fetch package: %v", label, err)
142			}
143			assertDeliveryMatches(t, d, deliveryBefore, label+": delivery")
144		}
145	
146		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
147		// 与身份、摘要或原因校验无关。原数据文件先挪到旁边，事后原样还原。
148		dataPath := filepath.Join(dir, dataName)
149		backupPath := dataPath + ".saved"
150		if err := os.Rename(dataPath, backupPath); err != nil {
151			t.Fatalf("backup data file: %v", err)
152		}
153		if err := os.Mkdir(dataPath, 0o755); err != nil {
154			t.Fatalf("block data path: %v", err)
155		}
156	
157		// 指定接收方、正确摘要、非空拒绝原因——全部业务条件满足，仅保存失败：
158		// 必须明确报错，且不能伪装成摘要冲突、参数非法或无权操作等业务结果。
159		clk.t = clk.t.Add(time.Hour)
160		failedAttemptAt := clk.t
161		if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "失败尝试的拒绝原因"); err == nil {
162			t.Fatal("receipt submission must fail when local save fails")
163		} else if errors.Is(err, ErrConflict) || errors.Is(err, ErrInvalidArgument) ||
164			errors.Is(err, ErrAccessDenied) || errors.Is(err, ErrDeactivated) ||
165			errors.Is(err, ErrNotFound) {
166			t.Fatalf("save failure surfaced as a business error: %v", err)
167		}
168		// 失败不能留下半截写入的临时文件。
169		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
170			t.Fatalf("failed save left a temp file: %v", statErr)
171		}
172	
173		// 失败后：交换仍待回执、无正式回执，审计与包全部维持提交前状态。
174		checkIntact("after failed save", s)
175	
176		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件）。
177		if err := s.Close(); err != nil {
178			t.Fatal(err)
179		}
180		if err := os.Remove(dataPath); err != nil {
181			t.Fatalf("unblock data path: %v", err)
182		}
183		if err := os.Rename(backupPath, dataPath); err != nil {
184			t.Fatalf("restore data file: %v", err)
185		}
186	
187		s2 := open()
188		t.Cleanup(func() { _ = s2.Close() })
189		// 重开后仍是提交前的正式数据：失败尝试没有变成回执或事件。
190		checkIntact("after reopen", s2)
191	
192		// 保存条件恢复后：同一接收方对同一份交换、以与失败尝试不同的非空原因
193		// 重新登记。失败尝试没有建立回执，不得返回已有回执冲突。
194		clk.t = clk.t.Add(time.Hour)
195		succeededAt := clk.t
196		if succeededAt.Equal(failedAttemptAt) {
197			t.Fatal("test clock must distinguish failed attempt from successful registration")
198		}
199		conf, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重试成功的拒绝原因")
200		if err != nil {
201			t.Fatalf("retry with a different reason after recovery: %v", err)
202		}
203		if conf.ExchangeID != x.ID || conf.Status != ExchangeRejected || conf.Outcome != ReceiptRejected {
204			t.Fatalf("bad confirmation: %+v", conf)
205		}
206		// 登记时间采用成功登记时的时间，而不是失败尝试的时间。
207		if !conf.RegisteredAt.Equal(succeededAt) {
208			t.Fatalf("registered at %v != successful attempt time %v (failed attempt was %v)",
209				conf.RegisteredAt, succeededAt, failedAttemptAt)
210		}
211	
212		// 内部视图：交换转为已拒绝，正式原因采用本次提交的文字；标识、原包
213		// 内容与摘要保持原样，没有因登记重新生成包。
214		want := snapshotExchange(xBefore)
215		want.Status = ExchangeRejected
216		want.Receipt = &Receipt{Outcome: ReceiptRejected, Reason: "重试成功的拒绝原因", RegisteredAt: succeededAt}
217		got, err := s2.GetExchange(doc, p.ID, x.ID)
218		if err != nil {
219			t.Fatal(err)
220		}
221		assertExchangeMatches(t, got, want, "exchange after successful retry")
222		if got.Receipt.Reason == "失败尝试的拒绝原因" {
223			t.Fatalf("failed attempt's reason became the official receipt: %+v", got.Receipt)
224		}
225		if got.ID != x.ID || got.Digest != x.Digest {
226			t.Fatalf("exchange identity or digest changed by receipt: %+v", got)
227		}
228		if recomputed := packageDigest(got.Package); recomputed != got.Digest {
229			t.Fatalf("package regenerated by receipt: digest %q, recomputed %q", got.Digest, recomputed)
230		}
231	
232		// 审计：相对提交前基线只新增一条由该接收方针对该交换的回执事件，
233		// 既有事件（含交换创建事件）保持顺序和内容。
234		audit, err := s2.AuditEvents(doc, p.ID)
235		if err != nil {
236			t.Fatal(err)
237		}
238		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
239			t.Fatalf("audit after retry:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
240		}
241		last := audit[len(audit)-1]
242		if last.Action != ActionReceipted || last.ObjectType != "exchange" ||
243			last.ObjectID != x.ID || last.ActorID != rcv.ID ||
244			last.PatientID != p.ID || !last.OccurredAt.Equal(succeededAt) {
245			t.Fatalf("unexpected new audit event: %+v", last)
246		}
247		if got := auditActions(audit)[ActionReceipted]; got != 1 {
248			t.Fatalf("receipt events = %d, want exactly 1 (failed attempt must not add one)", got)
249		}
250	
251		// 交换列表仍只有这一份交换，内容与内部视图一致。
252		xs, err := s2.ListExchanges(doc, p.ID)
253		if err != nil {
254			t.Fatal(err)
255		}
256		if len(xs) != 1 {
257			t.Fatalf("exchange count after retry = %d, want 1", len(xs))
258		}
259		assertExchangeMatches(t, xs[0], want, "listed exchange after retry")
260	
261		// 取包视图：状态转为已拒绝，摘要与包内容不变。
262		d, err := s2.FetchPackage(rcv, x.ID)
263		if err != nil {
264			t.Fatal(err)
265		}
266		if d.Status != ExchangeRejected || d.Digest != x.Digest {
267			t.Fatalf("delivery after retry: %+v", d)
268		}
269		assertDeliveryMatches(t, d, PackageDelivery{
270			ExchangeID: deliveryBefore.ExchangeID,
271			Status:     ExchangeRejected,
272			Digest:     deliveryBefore.Digest,
273			CreatedAt:  deliveryBefore.CreatedAt,
274			Package:    deliveryBefore.Package,
275		}, "delivery after retry")
276	
277		// 已有回执不可覆盖：改变原因再次提交返回 ErrConflict，正式回执与审计不变。
278		clk.t = clk.t.Add(time.Hour)
279		if _, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "试图覆盖的拒绝原因"); !errors.Is(err, ErrConflict) {
280			t.Fatalf("overwrite attempt err = %v, want ErrConflict", err)
281		}
282		got, err = s2.GetExchange(doc, p.ID, x.ID)
283		if err != nil {
284			t.Fatal(err)
285		}
286		assertExchangeMatches(t, got, want, "exchange after overwrite attempt")
287		if audit2 := mustAudit(t, s2, p.ID); !reflect.DeepEqual(audit2, audit) {
288			t.Fatalf("overwrite attempt changed audit:\nbefore: %+v\nafter:  %+v", audit, audit2)
289		}
290	
291		// 既有公开行为保留：相同回执重交返回原确认，不新增审计、不改状态。
292		conf2, err := s2.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重试成功的拒绝原因")
293		if err != nil {
294			t.Fatalf("idempotent resubmit: %v", err)
295		}
296		if conf2.ExchangeID != conf.ExchangeID || conf2.Status != conf.Status ||
297			conf2.Outcome != conf.Outcome || !conf2.RegisteredAt.Equal(conf.RegisteredAt) {
298			t.Fatalf("idempotent resubmit returned %+v, want original confirmation %+v", conf2, conf)
299		}
300		if n := len(mustAudit(t, s2, p.ID)); n != len(audit) {
301			t.Fatalf("idempotent resubmit added audit events: %d, want %d", n, len(audit))
302		}
303	
304		// 关闭后从同一数据位置重新打开：已拒绝状态、正式原因与登记时间完整
305		// 可见，失败尝试不作为另一份回执或事件出现。
306		if err := s2.Close(); err != nil {
307			t.Fatal(err)
308		}
309		s3 := open()
310		t.Cleanup(func() { _ = s3.Close() })
311	
312		got, err = s3.GetExchange(doc, p.ID, x.ID)
313		if err != nil {
314			t.Fatalf("get exchange after reopen: %v", err)
315		}
316		assertExchangeMatches(t, got, want, "exchange after reopen")
317	
318		audit3 := mustAudit(t, s3, p.ID)
319		if !reflect.DeepEqual(audit3, audit) {
320			t.Fatalf("audit after reopen:\nbefore: %+v\nafter:  %+v", audit, audit3)
321		}
322		var receiptEvents []AuditEvent
323		for _, ev := range audit3 {
324			if ev.Action == ActionReceipted {
325				receiptEvents = append(receiptEvents, ev)
326			}
327		}
328		if len(receiptEvents) != 1 || receiptEvents[0].ObjectID != x.ID ||
329			receiptEvents[0].ActorID != rcv.ID || !receiptEvents[0].OccurredAt.Equal(succeededAt) {
330			t.Fatalf("receipt events after reopen = %+v, want exactly one for %q at %v",
331				receiptEvents, x.ID, succeededAt)
332		}
333	}
