	xPending := newExchange("req-pending")

	// 首次登记接受回执：附带的原因文字必须被丢弃，不成为正式原因。
	clk.t = clk.t.Add(time.Hour)
	acceptedAt := clk.t
	confAcc, err := s.SubmitReceipt(rcv, xAcc.ID, xAcc.Digest, ReceiptAccepted, "首次登记时随手附带的接受文字")
	if err != nil {
